#!/usr/bin/env node
// Pull the Meteora DBC + DAMM v2 Anchor IDLs from their ON-CHAIN IDL accounts (mainnet, read-only)
// and write the swap-relevant subset (swap instructions, swap/curve/pool-init events and the types
// they reference) to src/idl/*.idl.ts. Decoding uses these through Anchor's BorshCoder.
//
//   MAINNET_RPC_URL=... npm run sync-idl -w @fumpad/meteora     (see scripts/rpc-url.mjs)
//
// Provenance (address of the IDL account, IDL version, sha256 of the full IDL) is written into the
// generated file header. The trimmed layouts were checked against the program sources
// (MeteoraAg/dynamic-bonding-curve event.rs / process_swap.rs, MeteoraAg/damm-v2 event.rs / ix_p_swap.rs).
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

import { PublicKey } from "@solana/web3.js";

import { mainnetRpcUrl, rpcCall } from "./rpc-url.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "../src/idl");
const url = mainnetRpcUrl();

const PROGRAMS = [
  {
    file: "dbc",
    constName: "DBC_IDL",
    id: "dbcij3LWUppWqq96dh6gJWwBifmcGfLSB5D4DuSMaqN",
    instructions: ["swap", "swap2", "swap2_with_transfer_hook", "migration_damm_v2"],
    events: ["EvtSwap", "EvtSwap2", "EvtSwap2WithTransferHook", "EvtCurveComplete", "EvtCurveCompleteWithTransferHook", "EvtInitializePool"],
  },
  {
    file: "damm_v2",
    constName: "DAMM_V2_IDL",
    id: "cpamdpZCGKUy5JxQXB4dcpGPiikHawvSWAd6mEn1sGG",
    instructions: ["swap", "swap2"],
    events: ["EvtSwap", "EvtSwap2", "EvtInitializePool"],
  },
];

/** Every `defined` type name reachable from a value. */
function refs(v, acc) {
  if (Array.isArray(v)) for (const x of v) refs(x, acc);
  else if (v && typeof v === "object") {
    if (v.defined) acc.add(typeof v.defined === "string" ? v.defined : v.defined.name);
    for (const x of Object.values(v)) refs(x, acc);
  }
  return acc;
}

for (const p of PROGRAMS) {
  const pid = new PublicKey(p.id);
  const [base] = PublicKey.findProgramAddressSync([], pid);
  const idlAddr = await PublicKey.createWithSeed(base, "anchor:idl", pid);
  const acc = await rpcCall(url, "getAccountInfo", [idlAddr.toBase58(), { encoding: "base64", commitment: "finalized" }]);
  if (!acc?.value) throw new Error(`${p.file}: no on-chain IDL account at ${idlAddr.toBase58()}`);
  const data = Buffer.from(acc.value.data[0], "base64");
  // Anchor IdlAccount: 8 disc ‖ authority (32) ‖ data_len u32 ‖ zlib(json)
  const json = inflateSync(data.subarray(44, 44 + data.readUInt32LE(40))).toString("utf8");
  const full = JSON.parse(json);
  if (full.address !== p.id) throw new Error(`${p.file}: IDL address ${full.address} != ${p.id}`);

  const instructions = full.instructions.filter((i) => p.instructions.includes(i.name));
  const events = (full.events ?? []).filter((e) => p.events.includes(e.name));
  const needed = new Set([...events.map((e) => e.name)]);
  refs(instructions.map((i) => i.args), needed);
  // Close over type references.
  for (let grew = true; grew; ) {
    grew = false;
    for (const t of full.types) {
      if (!needed.has(t.name)) continue;
      for (const r of refs(t.type, new Set())) if (!needed.has(r)) (needed.add(r), (grew = true));
    }
  }
  const types = full.types.filter((t) => needed.has(t.name));
  const trimmed = { address: full.address, metadata: full.metadata, instructions, accounts: [], events, errors: [], types };
  const sha = createHash("sha256").update(json).digest("hex");
  const ts =
    `// GENERATED by meteora/scripts/sync-idl.mjs — do not edit.\n` +
    `// Source: on-chain Anchor IDL account ${idlAddr.toBase58()} of ${p.id}\n` +
    `// (${full.metadata.name} ${full.metadata.version}; sha256 of the full IDL json: ${sha}).\n` +
    `// Trimmed to: instructions ${instructions.map((i) => i.name).join(", ")}; events ${events.map((e) => e.name).join(", ")}.\n` +
    `import type { Idl } from "@anchor-lang/core";\n\n` +
    `export const ${p.constName}: Idl = ${JSON.stringify(trimmed, null, 2)} as unknown as Idl;\n`;
  writeFileSync(join(out, `${p.file}.idl.ts`), ts);
  console.log(`${p.file}: ${full.metadata.name} ${full.metadata.version} → src/idl/${p.file}.idl.ts (${instructions.length} ix, ${events.length} events, ${types.length} types)`);
}
